import{_ as t,b as a,e as i,a8 as o}from"./chunks/framework.BXWQBDlf.js";const r="/assets/img_015.Bn3WNmy8.gif",h=JSON.parse('{"title":"Bitmap image","description":"","frontmatter":{"date":1789111954000,"authors":[],"tags":[],"head":[]},"headers":[],"relativePath":"guide/using-timage32/bitmap-image.md","filePath":"guide/using-timage32/bitmap-image.md","lastUpdated":1789111954000,"timestamp":1789111954000,"datetime":"2026-09-11T07:32:34.000Z"}'),m={name:"guide/using-timage32/bitmap-image.md"};function s(d,e,p,c,n,l){return a(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="bitmap-image" tabindex="-1">Bitmap image <a class="header-anchor" href="#bitmap-image" aria-label="Permalink to &quot;Bitmap image&quot;">​</a></h1><p>Internally a <code>TImage32</code> control represents the bitmap image with a <a href="/api/GR32/TBitmap32/">TBitmap32</a> object. This bitmap is surfaced by the <a href="/api/GR32_Image/TCustomImage32/Bitmap">Bitmap</a> property. The scale and location of the bitmap within the control is determined by the following properties:</p><table tabindex="0"><thead><tr><th>Property</th><th>Description</th></tr></thead><tbody><tr><td><a href="/api/GR32_Image/TCustomImage32/BitmapAlign">BitmapAlign</a></td><td>Specifies if the bitmap image is positioned at the top-left corner of the control (<code>baTopLeft</code>), centered (<code>baCenter</code>), tiled (<code>baTile</code>) or it its exact location is determined by <a href="/api/GR32_Image/TCustomImage32/OffsetHorz">OffsetHorz</a> and <a href="/api/GR32_Image/TCustomImage32/OffsetVert">OffsetVert</a> properties.</td></tr><tr><td><a href="/api/GR32_Image/TCustomImage32/ScaleMode">ScaleMode</a></td><td>Indicates if the bitmap image is displayed with its original size (<code>smNormal</code>), stretched to fit the control’s boundaries (<code>smStretch</code>), proportionally resized to fit the control’s boundaries(<code>smResize</code>) or proportionally scaled using its <a href="/api/GR32_Image/TCustomImage32/Scale">Scale</a> property (<code>smScale</code>).</td></tr></tbody></table><p><img src="'+r+'" alt=""></p><p>The bitmap image is combined with the back-buffer according to its <a href="/api/GR32/TCustomBitmap32/DrawMode">DrawMode</a> property. If its <code>DrawMode</code> is <code>dmCustom</code>, the bitmap will fire a series of <a href="/api/GR32/TCustomBitmap32/OnPixelCombine">OnPixelCombine</a> events.</p>',5)])])}const f=t(m,[["render",s]]);export{h as __pageData,f as default};
